from pathlib import Path
import subprocess, yaml
base='cbc0c41'
paths=subprocess.check_output(['git','diff','--name-only',f'{base}...HEAD'], text=True).splitlines()
catalog=yaml.safe_load(Path('contracts/release/source-ownership-catalog.yaml').read_text())
owners=[]
for field in ('owners','tooling_owners'):
    owners += catalog.get(field,[])
def match(path, root):
    root=root.removesuffix('/**')
    return path == root or path.startswith(root + '/')
for path in paths:
    matches=[]
    for entry in owners:
        for root in entry.get('source_paths',[]):
            if match(path, root):
                matches.append(entry['owner_id'])
    print(f'{path}: {", ".join(matches) or "UNMAPPED"}')
